	return {
		profile
	};
}

import * as api from '$lib/api.js';
import { error, fail } from '@sveltejs/kit';
import { get_articles } from './get_articles';

/** @type {import('./$types').PageServerLoad} */
export async function load(event) {
	const { articles, page } = await get_articles(event, 'author');
	return { articles, page };
}

/** @type {import('./$types').Actions} */
export const actions = {
	toggleFollow: async ({ locals, params, request }) => {
		if (!locals.user) error(401);

		const data = await request.formData();
		const following = data.get('following') !== 'on';

		const result = following
			? await api.post(`profiles/${params.user}/follow`, null, locals.user.token)
			: await api.del(`profiles/${params.user}/follow`, locals.user.token);

		if (result.errors) {
			return fail(422, result);
		}
	}
};

import { get_articles } from '../get_articles';

/** @type {import('./$types').PageServerLoad} */
export async function load(event) {
	const { articles, page } = await get_articles(event, 'favorited');
	return { articles, page };
}

import * as api from '$lib/api.js';
import { page_size } from '$lib/constants.js';

export async function get_articles({ url, params, locals }, type) {
	const p = +url.searchParams.get('page') || 1;

	const q = new URLSearchParams();
	q.set('limit', page_size);
	q.set('offset', (p - 1) * page_size);
	q.set(type, params.user);

	const { articles, articlesCount } = await api.get(
		`articles?${q}`,
		locals.user && locals.user.token
	);

	return {
		articles,
		pages: Math.ceil(articlesCount / page_size)
	};
}

import { fail, redirect } from '@sveltejs/kit';
import * as api from '$lib/api.js';

/** @type {import('./$types').PageServerLoad} */
export async function load({ parent }) {
	const { user } = await parent();
	if (user) redirect(307, '/');
}

/** @type {import('./$types').Actions} */
export const actions = {
	default: async ({ cookies, request }) => {
		const data = await request.formData();

		const user = {
			username: data.get('username'),
			email: data.get('email'),
			password: data.get('password')
		};

		const body = await api.post('users', { user });

		if (body.errors) {
			return fail(401, body);
		}

		const value = btoa(JSON.stringify(body.user));
		cookies.set('jwt', value, { path: '/' });

		redirect(307, '/');
	}
};

import { error, fail, redirect } from '@sveltejs/kit';
import * as api from '$lib/api.js';

export function load({ locals }) {
	if (!locals.user) redirect(302, '/login');
}

/** @type {import('./$types').Actions} */
export const actions = {
	logout: async ({ cookies, locals }) => {
		cookies.delete('jwt', { path: '/' });
		locals.user = null;
	},

	save: async ({ cookies, locals, request }) => {
		if (!locals.user) error(401);

		const data = await request.formData();

		const user = {
			username: data.get('username'),
			email: data.get('email'),
			password: data.get('password'),
			image: data.get('image'),
			bio: data.get('bio')
		};

		const body = await api.put('user', { user }, locals.user.token);
		if (body.errors) return fail(400, body.errors);

		const value = btoa(JSON.stringify(body.user));
		cookies.set('jwt', value, { path: '/' });

		locals.user = body.user;
	}
};
